function E(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){
  return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function $(id){return document.getElementById(id)}
function init(){
  var r=$("cb");
  if(!r||!$("cb-picks")){ if(++tries!==60) return setTimeout(init,100); return; }
  if(r.getAttribute("data-init")==="1") return;
  r.setAttribute("data-init","1"); build();
}
function build(){
  var ks={},ts={},cs={};
  PLANS.forEach(function(p){ks[p.carrier]=1;ts[p.type]=1;p.cty.forEach(function(c){cs[c]=1})});
  fill("cb-carrier",Object.keys(ks).sort());
  fill("cb-type",Object.keys(ts).sort());
  fill("cb-county",Object.keys(cs).sort());
  ["cb-carrier","cb-county","cb-type"].forEach(function(id){
    $(id).addEventListener("change",renderPicks)});
  ["cb-years","cb-title","cb-note"].forEach(function(id){
    $(id).addEventListener("change",draw); $(id).addEventListener("input",draw)});
  $("cb-all").addEventListener("click",function(){
    var b=$("cb-picks").querySelectorAll("input[type=checkbox]"),n=0;
    for(var i=0;i!==b.length&&n!==MAX;i++){if(b[i].offsetParent!==null){b[i].checked=true;n++}}
    draw()});
  $("cb-none").addEventListener("click",function(){
    var b=$("cb-picks").querySelectorAll("input[type=checkbox]");
    for(var i=0;i!==b.length;i++)b[i].checked=false; draw()});
  $("cb-edit").addEventListener("click",function(){
    EDIT=!EDIT; this.textContent="Edit: "+(EDIT?"on":"off"); this.className=EDIT?"pri":"";
    var c=$("cb-out").querySelectorAll(".big,.sm");
    for(var i=0;i!==c.length;i++)c[i].contentEditable=EDIT?"true":"false"});
  function openPrintWindow(autoPrint){
    var s=$("sheet");
    if(!s){alert("Build a chart first.");return null}
    var w=window.open("","_blank","width=1400,height=900");
    if(!w){alert("Allow pop-ups for this site to print or save the chart.");return null}
    var d=w.document;
    d.open();
    d.write(LT+"!doctype html"+GT+LT+"html"+GT+LT+"head"+GT+
      LT+"meta charset=\"utf-8\""+GT+
      LT+"title"+GT+"Chart"+LT+"/title"+GT+
      LT+"link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Barlow+Semi+Condensed:wght@500;600;700&display=swap\""+GT+
      LT+"style"+GT+PCSS+LT+"/style"+GT+LT+"/head"+GT+LT+"body"+GT+
      LT+"div id=\"fitwrap\""+GT+s.outerHTML+LT+"/div"+GT+
      LT+"/body"+GT+LT+"/html"+GT);
    d.close(); w.focus();
    // scale the chart so it fits ONE landscape page
    setTimeout(function(){
      try{
        var el=w.document.getElementById("sheet"),
            wrap=w.document.getElementById("fitwrap"),
            PW=1004, PH=752,
            cw=el.scrollWidth, chh=el.scrollHeight,
            k=Math.min(PW/cw, PH/chh, 1);
        wrap.style.width=PW+"px";
        wrap.style.height=PH+"px";
        wrap.style.overflow="hidden";
        el.style.transformOrigin="top left";
        el.style.transform="scale("+k+")";
        el.style.width=cw+"px";
      }catch(e){}
      if(autoPrint) setTimeout(function(){w.print()},350);
    },600);
    return w;
  }
  $("cb-print").addEventListener("click",function(){openPrintWindow(true)});
  var sp=$("cb-save"); if(sp) sp.addEventListener("click",function(){openPrintWindow(true)});
  renderPicks();
}
function fill(id,arr){
  var s=$(id); arr.forEach(function(v){
    var o=document.createElement("option"); o.textContent=v; s.appendChild(o)})}
function shown(){
  var k=$("cb-carrier").value,c=$("cb-county").value,t=$("cb-type").value;
  return PLANS.filter(function(p){
    return (!k||p.carrier===k)&&(!t||p.type===t)&&(!c||p.cty.indexOf(c)>-1)})
}
function renderPicks(){
  var list=shown(),h="";
  list.forEach(function(p){
    h+=''+LT+'label class="pk"'+GT+''+LT+'input type="checkbox" value="'+E(p.cms)+'">'+
       ''+LT+'span'+GT+''+LT+'b'+GT+''+E(p.name)+''+LT+'/b'+GT+''+LT+'br'+GT+''+LT+'span class="cd"'+GT+''+E(p.cms)+
       (p.net?" · "+E(p.net):"")+" · "+E(p.carrier)+''+LT+'/span'+GT+''+LT+'/span'+GT+''+LT+'/label'+GT+''});
  $("cb-picks").innerHTML=h||''+LT+'div class="empty"'+GT+'No plans match those filters.'+LT+'/div'+GT+'';
  $("cb-count").textContent=list.length+" plans match";
  var b=$("cb-picks").querySelectorAll("input");
  for(var i=0;i!==b.length;i++)b[i].addEventListener("change",function(){
    var on=$("cb-picks").querySelectorAll("input:checked");
    if(on.length===MAX+1){this.checked=false;alert("Up to "+MAX+" plans per chart.");return}
    draw()});
  draw();
}
function picked(){
  var out=[],b=$("cb-picks").querySelectorAll("input:checked");
  for(var i=0;i!==b.length;i++){
    var v=b[i].value;
    PLANS.forEach(function(p){if(p.cms===v)out.push(p)})}
  return out;
}
function cell(p,key,mode){
  function one(src,tag){
    var o=(p[src]||{})[key]||{},v=o.v||"";
    if(!v) return ''+LT+'div class="big"'+GT+'&mdash;'+LT+'/div'+GT+'';
    var parts=v.split("|"),
        fl=(o.p==="fl")?''+LT+'sup class="fl"'+GT+'FL'+LT+'/sup'+GT+'':"";
    var s=''+LT+'div class="big"'+GT+''+E(parts[0])+fl+''+LT+'/div'+GT+'';
    if(parts[1])s+=''+LT+'div class="sm"'+GT+''+E(parts[1])+''+LT+'/div'+GT+'';
    return s;
  }
  if(mode==="both")
    return ''+LT+'div class="pair"'+GT+''+LT+'div'+GT+''+one("c26")+''+LT+'/div'+GT+''+LT+'div'+GT+''+one("c27")+''+LT+'/div'+GT+''+LT+'/div'+GT+'';
  return one(mode==="26"?"c26":"c27");
}
function draw(){
  var sel=picked(),mode=$("cb-years").value;
  if(!sel.length){$("cb-out").innerHTML=''+LT+'div class="empty"'+GT+'Tick plans above to build a chart.'+LT+'/div'+GT+'';return}
  var county=$("cb-county").value,carrier=$("cb-carrier").value;
  var auto=(carrier||"2027 PLAN")+" CHART"+(county?" — "+county.toUpperCase()+" COUNTY":"");
  if(mode==="both")auto=(carrier||"PLAN")+" 2026 VS 2027"+(county?" — "+county.toUpperCase()+" COUNTY":"");
  var title=$("cb-title").value.trim()||auto;
  var note=$("cb-note").value.trim();
  var yrLabel=mode==="both"?"2026 / 2027":(mode==="26"?"2026":"2027");
  var head="";
  sel.forEach(function(p){
    head+=''+LT+'th'+GT+''+LT+'div class="pt"'+GT+''+E(p.name)+''+LT+'/div'+GT+''+LT+'div class="pcode"'+GT+''+E(p.cms)+
      (p.net?" · "+E(p.net):"")+''+LT+'/div'+GT+''+
      (mode==="both"?''+LT+'div class="yrs"'+GT+''+LT+'span'+GT+'2026'+LT+'/span'+GT+''+LT+'span'+GT+'2027'+LT+'/span'+GT+''+LT+'/div'+GT+'':"")+''+LT+'/th'+GT+''});
  var body="";
  ROWS.forEach(function(r){
    body+=''+LT+'tr'+GT+''+LT+'th class="rl"'+GT+''+E(r[0])+''+LT+'/th'+GT+'';
    sel.forEach(function(p){body+=''+LT+'td'+GT+''+cell(p,r[1],mode)+''+LT+'/td'+GT+''});
    body+=''+LT+'/tr'+GT+''});
  body+=''+LT+'tr class="rxh"'+GT+''+LT+'th class="rl"'+GT+'RX COPAYS'+LT+'/th'+GT+'';
  sel.forEach(function(){body+=''+LT+'td'+GT+''+LT+'/td'+GT+''}); body+=''+LT+'/tr'+GT+'';
  RX.forEach(function(r){
    body+=''+LT+'tr'+GT+''+LT+'th class="rl"'+GT+''+E(r[0])+''+LT+'/th'+GT+'';
    sel.forEach(function(p){body+=''+LT+'td'+GT+''+cell(p,r[1],mode)+''+LT+'/td'+GT+''});
    body+=''+LT+'/tr'+GT+''});
  $("cb-out").innerHTML=''+LT+'div id="sheet"'+GT+''+LT+'div class="top"'+GT+''+LT+'span'+GT+'FOR INTERNAL AGENT USE ONLY'+LT+'/span'+GT+''+
    (note?''+LT+'span style="color:#F2B233;font-weight:700"'+GT+''+E(note)+''+LT+'/span'+GT+'':'')+''+LT+'/div'+GT+''+
    ''+LT+'div class="hd"'+GT+''+LT+'div class="yr"'+GT+''+E(yrLabel)+''+LT+'br'+GT+'BENEFITS'+LT+'/div'+GT+''+LT+'h1'+GT+''+E(title)+''+LT+'/h1'+GT+''+LT+'/div'+GT+''+
    ''+LT+'table'+GT+''+LT+'thead'+GT+''+LT+'tr'+GT+''+LT+'th class="rl"'+GT+''+LT+'/th'+GT+''+head+''+LT+'/tr'+GT+''+LT+'/thead'+GT+''+LT+'tbody'+GT+''+body+''+LT+'/tbody'+GT+''+LT+'/table'+GT+''+
    ''+LT+'div class="key"'+GT+''+LT+'b'+GT+'FL'+LT+'/b'+GT+' = carrier First Look, '+LT+'b'+GT+'not CMS-approved'+LT+'/b'+GT+' — subject to change. '+
    'Unmarked values are CMS-published. 2027 benefits may not be discussed with beneficiaries before Oct 1.'+LT+'/div'+GT+''+
    ''+LT+'div class="ft"'+GT+'Sources: CMS Landscape and PBP files (2026); carrier First Look documents (2027).'+LT+'/div'+GT+''+LT+'/div'+GT+'';
  if(EDIT){var c=$("cb-out").querySelectorAll(".big,.sm");
    for(var i=0;i!==c.length;i++)c[i].contentEditable="true"}
}
